const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const northernHemisphere = ee.Geometry.Polygon([
    [[-180, 0], [180, 0], [180, 90], [-180, 90], [-180, 0]]
  ]);

  const date2019Start = '2019-01-01';
  const date2019End = '2019-12-31';
  const date2020Start = '2020-01-01';
  const date2020End = '2020-12-31';

  // 2. Data Acquisition & Check
  const col2019 = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_NO2')
    .filterDate(date2019Start, date2019End)
    .filterBounds(northernHemisphere)
    .filter(ee.Filter.gt('qa_value', 0.75));

  const col2020 = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_NO2')
    .filterDate(date2020Start, date2020End)
    .filterBounds(northernHemisphere)
    .filter(ee.Filter.gt('qa_value', 0.75));

  const size2019 = await col2019.size().getInfo();
  const size2020 = await col2020.size().getInfo();

  console.log(`2019 Images: ${size2019}`);
  console.log(`2020 Images: ${size2020}`);

  if (size2019 === 0 || size2020 === 0) {
    console.log("No data found for one or both years.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Calculate mean NO2 for each year
  const no2_2019 = col2019.select('tropospheric_NO2_column_number_density').mean();
  const no2_2020 = col2020.select('tropospheric_NO2_column_number_density').mean();

  // 4. Calculation with pixel count validation
  const stats2019 = await no2_2019.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: northernHemisphere,
    scale: 5000,
    maxPixels: 1e9
  }).getInfo();

  const stats2020 = await no2_2020.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: northernHemisphere,
    scale: 5000,
    maxPixels: 1e9
  }).getInfo();

  const mean2019 = stats2019['tropospheric_NO2_column_number_density_mean'];
  const count2019 = stats2019['tropospheric_NO2_column_number_density_count'];
  const mean2020 = stats2020['tropospheric_NO2_column_number_density_mean'];
  const count2020 = stats2020['tropospheric_NO2_column_number_density_count'];

  console.log(`2019: Mean NO2 = ${mean2019}, Pixels = ${count2019}`);
  console.log(`2020: Mean NO2 = ${mean2020}, Pixels = ${count2020}`);

  // 5. Validation & Final Answer
  if (count2019 === 0 || count2020 === 0) {
    console.log("No valid pixels after masking.");
    console.log("<answer>C2</answer>");
    return;
  }

  if (mean2019 === null || mean2019 === undefined || 
      mean2020 === null || mean2020 === undefined ||
      isNaN(mean2019) || isNaN(mean2020)) {
    console.log("Calculation failed - invalid results.");
    console.log("<answer>C3</answer>");
    return;
  }

  const percentChange = ((mean2020 - mean2019) / mean2019) * 100;
  console.log(`Change: ${percentChange.toFixed(2)}%`);

  if (mean2020 > mean2019) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
